import json
import sys
from datetime import datetime, timezone
import time
import urllib.request
import urllib.parse

BASE = "https://api.github.com"
OWNER = "cli"
REPO = "cli"

start = datetime(2024, 12, 1, 0, 0, 0, tzinfo=timezone.utc)
end = datetime(2024, 12, 31, 23, 59, 59, tzinfo=timezone.utc)

USER_AGENT = "codex-cli-report"


def get_json(url, params):
    qs = urllib.parse.urlencode(params)
    full = f"{url}?{qs}"
    req = urllib.request.Request(full, headers={"User-Agent": USER_AGENT, "Accept": "application/vnd.github+json"})
    with urllib.request.urlopen(req) as resp:
        data = resp.read()
        # rate limit headers available but not needed here
        return json.loads(data)


def parse_dt(s):
    if not s:
        return None
    # GitHub uses ISO 8601 with Z
    return datetime.strptime(s, "%Y-%m-%dT%H:%M:%SZ").replace(tzinfo=timezone.utc)


def fetch_pulls_created_in_range():
    pulls = []
    page = 1
    while True:
        params = {
            "state": "all",
            "sort": "created",
            "direction": "desc",
            "per_page": 100,
            "page": page,
        }
        data = get_json(f"{BASE}/repos/{OWNER}/{REPO}/pulls", params)
        if not data:
            break
        # data is list of PRs
        for pr in data:
            created = parse_dt(pr.get("created_at"))
            if created is None:
                continue
            if start <= created <= end:
                pulls.append(pr)
        # if last item older than start, stop
        last_created = parse_dt(data[-1].get("created_at"))
        if last_created and last_created < start:
            break
        page += 1
    return pulls


def fetch_issues_created_in_range():
    issues = []
    page = 1
    while True:
        params = {
            "state": "all",
            "sort": "created",
            "direction": "desc",
            "per_page": 100,
            "page": page,
        }
        data = get_json(f"{BASE}/repos/{OWNER}/{REPO}/issues", params)
        if not data:
            break
        for issue in data:
            # skip PRs
            if "pull_request" in issue:
                continue
            created = parse_dt(issue.get("created_at"))
            if created is None:
                continue
            if start <= created <= end:
                issues.append(issue)
        last_created = parse_dt(data[-1].get("created_at"))
        if last_created and last_created < start:
            break
        page += 1
    return issues


pulls = fetch_pulls_created_in_range()
issues = fetch_issues_created_in_range()

# PR metrics
pr_total = len(pulls)
merged = 0
closed_non_merged = 0
merge_days = []
contrib_counts = {}
for pr in pulls:
    user = pr.get("user", {}) or {}
    login = user.get("login") or "unknown"
    contrib_counts[login] = contrib_counts.get(login, 0) + 1
    merged_at = parse_dt(pr.get("merged_at"))
    created_at = parse_dt(pr.get("created_at"))
    state = pr.get("state")
    if merged_at:
        merged += 1
        if created_at:
            delta_days = (merged_at - created_at).total_seconds() / 86400.0
            merge_days.append(delta_days)
    elif state == "closed":
        closed_non_merged += 1

if merge_days:
    avg_merge_days = round(sum(merge_days) / len(merge_days), 1)
else:
    avg_merge_days = 0.0

# Top contributor
if contrib_counts:
    top_contributor = sorted(contrib_counts.items(), key=lambda x: (-x[1], x[0]))[0][0]
else:
    top_contributor = ""

# Issue metrics
issue_total = len(issues)
bug_total = 0
resolved_bugs = 0
for issue in issues:
    labels = issue.get("labels", []) or []
    is_bug = False
    for label in labels:
        name = (label.get("name") or "").lower()
        if "bug" in name:
            is_bug = True
            break
    if is_bug:
        bug_total += 1
        closed_at = parse_dt(issue.get("closed_at"))
        if closed_at and start <= closed_at <= end:
            resolved_bugs += 1

report = {
    "pr": {
        "total": pr_total,
        "merged": merged,
        "closed": closed_non_merged,
        "avg_merge_days": avg_merge_days,
        "top_contributor": top_contributor,
    },
    "issue": {
        "total": issue_total,
        "bug": bug_total,
        "resolved_bugs": resolved_bugs,
    },
}

with open("/app/report.json", "w", encoding="utf-8") as f:
    json.dump(report, f, indent=2)

print("Wrote /app/report.json")
PY"}

